def table(headers,rows,widths=None,size=9):
 t=d.add_table(rows=1,cols=len(headers));t.autofit=False
 if widths:
  for col,w in zip(t.columns,widths):col.width=Inches(w)
 for cell,text in zip(t.rows[0].cells,headers):cell.text=str(text)
 for row in rows:
  for cell,text in zip(t.add_row().cells,row):cell.text=str(text).replace('RandomForest_leaf','RF leaf ').replace('Logistic_C','Logistic C ')
 for ri,row in enumerate(t.rows):
  pr=row._tr.get_or_add_trPr();pr.append(OxmlElement('w:cantSplit'))
  if ri==0:pr.append(OxmlElement('w:tblHeader'))
  for ci,cell in enumerate(row.cells):
   if widths:cell.width=Inches(widths[ci])
   tc=cell._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
   tc.append(b);sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'E8EEF1' if ri==0 else 'F7F9FA' if ri%2==0 else 'FFFFFF');tc.append(sh)
   mar=OxmlElement('w:tcMar')
   for edge in ['top','bottom','left','right']:
    e=OxmlElement('w:'+edge);e.set(qn('w:w'),'75');e.set(qn('w:type'),'dxa');mar.append(e)
   tc.append(mar)
   for a in cell.paragraphs:
    a.alignment=WD_ALIGN_PARAGRAPH.CENTER;a.paragraph_format.space_after=Pt(2);a.paragraph_format.space_before=Pt(2);a.paragraph_format.line_spacing=1.05
    for r in a.runs:r.font.size=Pt(size);r.font.name='Arial';r.bold=ri==0
 d.add_paragraph().paragraph_format.space_after=Pt(1)
